[GQL-OP paged_aliases]
  query {
    page1: products(storeId: "{{STORE_ID}}" currencyCode: "USD" first: 2 filter: "category.subtree:@td(VIRTUAL_CATALOG_B2B.id)") { items { id } }
    page2: products(storeId: "{{STORE_ID}}" currencyCode: "USD" first: 2 after: "{{CURSOR}}" filter: "category.subtree:@td(VIRTUAL_CATALOG_B2B.id)") { items { id } }
  }
[GQL-EXEC paged_aliases]

[GQL-OP find_eur]
  query { products(storeId: "{{STORE_ID}}" currencyCode: "EUR" first: 1 filter: "category.subtree:@td(VIRTUAL_CATALOG_B2B.id) price.EUR:(0.01 TO)") { items { id } } }
[GQL-EXEC find_eur]
[GQL-CAPTURE find_eur.data.products.items.0.id → EUR_PROD_ID]
[GQL-OP currency_dedup]
  query {
    usd: products(storeId: "{{STORE_ID}}" currencyCode: "USD" first: 1 productIds: ["{{EUR_PROD_ID}}"]) { items { id price { actual { amount currency { code } } } } }
    eur: products(storeId: "{{STORE_ID}}" currencyCode: "EUR" first: 1 productIds: ["{{EUR_PROD_ID}}"]) { items { id price { actual { amount currency { code } } } } }
  }
[GQL-EXEC currency_dedup]

[GQL-OP discover_ids]
  query { products(storeId: "{{STORE_ID}}" currencyCode: "USD" first: 3 filter: "category.subtree:@td(VIRTUAL_CATALOG_B2B.id)") { items { id } } }
[GQL-EXEC discover_ids]
[GQL-CAPTURE discover_ids.data.products.items.0.id → ID1]
[GQL-CAPTURE discover_ids.data.products.items.1.id → ID2]
[GQL-CAPTURE discover_ids.data.products.items.2.id → ID3]
[GQL-OP overlap_ids]
  query {
    setA: products(storeId: "{{STORE_ID}}" currencyCode: "USD" first: 10 productIds: ["{{ID1}}", "{{ID2}}"]) { totalCount items { id } }
    setB: products(storeId: "{{STORE_ID}}" currencyCode: "USD" first: 10 productIds: ["{{ID2}}", "{{ID3}}"]) { totalCount items { id } }
  }
[GQL-EXEC overlap_ids]

[GQL-OP cat_negative_control]
  query {
    narrow: categories(storeId: "{{STORE_ID}}" cultureName: "en-US" first: 2) { totalCount items { id name childCategories { id } } }
    wide: categories(storeId: "{{STORE_ID}}" cultureName: "en-US" first: 5) { totalCount items { id name childCategories { id } } }
  }
[GQL-EXEC cat_negative_control]
[GQL-CAPTURE cat_negative_control.data.narrow.items.0.id → NARROW_ID0]
[GQL-CAPTURE cat_negative_control.data.wide.items.0.id → WIDE_ID0]

[GQL-OP facet_filter_combo]
  query {
    wide: products(storeId: "{{STORE_ID}}" currencyCode: "USD" first: 1 filter: "category.subtree:@td(VIRTUAL_CATALOG_B2B.id)" facet: "Brand") { totalCount term_facets { name terms { term count } } }
    narrow: products(storeId: "{{STORE_ID}}" currencyCode: "USD" first: 1 filter: "category.subtree:@td(VIRTUAL_CATALOG_B2B.id) Brand:{{brand_a}}" facet: "Brand") { totalCount term_facets { name terms { term count } } }
  }
[GQL-EXEC facet_filter_combo]
